struct Draft; struct Published;

struct Post<S> { content: String, _state: std::marker::PhantomData<S> }

impl Post<Draft> {
    fn publish(self) -> Post<Published> {
        Post { content: self.content, _state: std::marker::PhantomData }
    }
}
// Post<Published> has no publish(); Post<Draft> has no view_count().

#[typestate]
mod traffic_light {
    #[automaton] pub struct TrafficLight { pub cycles: u64 }
    #[state] pub struct Green;  #[state] pub struct Red;
    pub trait Green { fn to_red(self) -> Red; }
    pub trait Red   { fn to_green(self) -> Green; fn turn_off(self); }
}

